  /\d+\s+дн\p{L}*\s+в\s+офис/iu,
  /офис\p{L}*\s+\d+\s+дн/iu,
];

const officePatterns = [
  /работа\s+в\s+офис/iu,
  /офисн\p{L}*\s+формат/iu,
  /только\s+офис/iu,
  /исключительно\s+в\s+офис/iu,
  /работа\s+из\s+офиса/iu,
  /\bon[\s-]*site\b/i,
  /\bonsite\b/i,
  /\boffice[\s-]*based\b/i,
];

const tbilisiPatterns = [
  /тбилиси/iu,
  /(?:^|[^a-z])tbilisi(?:$|[^a-z])/i,
  /თბილისი/u,
];

const georgiaCountryPatterns = [
  /грузи\p{L}*/iu,
  /საქართველო/u,
  /\btbilisi\s*,?\s*georgia\b/i,
  /\bgeorgia\s*,?\s*tbilisi\b/i,
  /\bgeorgia\s*,?\s*(?:country|europe|caucasus)\b/i,
];

function classifyWorkFormat(text) {
  const remoteExplicitHigh = hasAny(remoteExplicitHighPatterns, text);
  const remotePositive = hasAny(remotePositivePatterns, text);
  const remoteDenied = hasAny(remoteDeniedPatterns, text);
  const hybrid = hasAny(hybridPatterns, text);
  const office = hasAny(officePatterns, text);

  const conflict =
    (remotePositive && remoteDenied) ||
    (remotePositive && hybrid) ||
    (remotePositive && office && !remoteExplicitHigh);

  // Strong explicit full-remote signal wins, but conflict is preserved.
  if (remoteExplicitHigh && !remoteDenied) {
    return {
      hint: 'remote',
      confidence: conflict ? 'medium' : 'high',
      conflict,
      remote_signal: true,
      hybrid_signal: hybrid,
      office_signal: office,
      remote_denied_signal: false,
    };
  }

  // Explicit denial of remote takes precedence over weak "remote" mentions.
  if (remoteDenied) {
    if (hybrid) {
      return {
        hint: 'hybrid',
        confidence: 'medium',
        conflict,
        remote_signal: false,
        hybrid_signal: true,
        office_signal: office,
        remote_denied_signal: true,
      };
    }

    if (office) {
      return {
        hint: 'office',
        confidence: 'high',
        conflict,
        remote_signal: false,
        hybrid_signal: false,
        office_signal: true,
        remote_denied_signal: true,
      };
    }
  }

  if (hybrid) {
    return {
      hint: 'hybrid',
      confidence: conflict ? 'low' : 'medium',
      conflict,
      remote_signal: remotePositive && !remoteDenied,
      hybrid_signal: true,
      office_signal: office,
      remote_denied_signal: remoteDenied,
    };
  }

  if (remotePositive && !remoteDenied) {
    return {
      hint: 'remote',
      confidence: conflict ? 'medium' : 'medium',
      conflict,
      remote_signal: true,
      hybrid_signal: false,
      office_signal: office,
      remote_denied_signal: false,
    };
  }

  if (office) {
    return {
      hint: 'office',
      confidence: 'medium',
      conflict,
      remote_signal: false,
      hybrid_signal: false,
      office_signal: true,
      remote_denied_signal: remoteDenied,
    };
  }

  return {
    hint: 'unknown',
    confidence: 'low',
    conflict,
    remote_signal: false,
    hybrid_signal: false,
    office_signal: false,
    remote_denied_signal: remoteDenied,
  };
}

function classifyGeoPolicy(workFormat, text) {
  const isTbilisi = hasAny(tbilisiPatterns, text);
  const isGeorgia = hasAny(georgiaCountryPatterns, text) || isTbilisi;

  let policy = 'needs_full_page_check';

  if (workFormat.hint === 'remote' && !workFormat.remote_denied_signal) {
    policy = 'allowed_remote';
  } else if (
    isTbilisi &&
    (workFormat.hint === 'hybrid' || workFormat.hint === 'office')
  ) {
    policy = 'allowed_tbilisi';
  } else if (isTbilisi && workFormat.hint === 'unknown') {
    policy = 'possible_tbilisi_needs_format_check';
  } else if (
    isGeorgia &&
    !isTbilisi &&
    (workFormat.hint === 'hybrid' || workFormat.hint === 'office')
  ) {
    policy = 'likely_reject_non_tbilisi_georgia';
  } else if (
    !isTbilisi &&
    (workFormat.hint === 'hybrid' || workFormat.hint === 'office')
  ) {
    policy = 'needs_full_page_location_check';
  }

  return {
    tbilisi_signal: isTbilisi,
    georgia_signal: isGeorgia,
    policy,
    needs_full_page_geo_check: !['allowed_remote', 'allowed_tbilisi'].includes(policy),
  };
}

// ============================================================
// 8. EVIDENCE COLLECTION
// ============================================================

function collectAiEvidence(parsed) {
  const titleText = parsed.vacancy_title_normalized;
  const skillsText = parsed.rss_skills_text;
  const narrativeText = parsed.rss_narrative_text;
  const fullText = parsed.rss_full_text;

  const aiTitleMatches = matchPatterns(aiPatterns, titleText);
  const aiSkillMatches = matchPatterns(aiPatterns, skillsText);
  const aiNarrativeMatches = matchPatterns(aiPatterns, narrativeText);

  const implTitleMatches = matchPatterns(aiImplementationPatterns, titleText);
  const implSkillMatches = matchPatterns(aiImplementationPatterns, skillsText);
  const implNarrativeMatches = matchPatterns(aiImplementationPatterns, narrativeText);

  const genericTitleMatches = matchPatterns(genericTechPatterns, titleText);
  const genericSkillMatches = matchPatterns(genericTechPatterns, skillsText);
  const genericNarrativeMatches = matchPatterns(genericTechPatterns, narrativeText);

  // Analyze task/requirement semantics on the narrative part, not on duplicated title/skills.
  // This prevents false incidental-AI matches caused by Habr boilerplate.
  const semanticTaskText = narrativeText || fullText;
  const coreWorkMatches = matchPatterns(coreAiWorkPatterns, semanticTaskText);
  const incidentalMatches = matchPatterns(incidentalAiPatterns, semanticTaskText);

  const allAiMatches = uniqueBy(
    [...aiTitleMatches, ...aiSkillMatches, ...aiNarrativeMatches],
    (match) => `${match.category}:${match.name}`
  );

  const allImplMatches = uniqueBy(
    [...implTitleMatches, ...implSkillMatches, ...implNarrativeMatches],
    (match) => `${match.category}:${match.name}`
  );

  const allGenericMatches = uniqueBy(
    [...genericTitleMatches, ...genericSkillMatches, ...genericNarrativeMatches],
    (match) => `${match.category}:${match.name}`
  );

  const allAiCategories = categories(allAiMatches);
  const substantiveAiCategories = allAiCategories.filter(
    (category) => category !== 'GENERAL_AI'
  );

  const tierACount = countIntersection(substantiveAiCategories, AI_TIER_A);
  const tierBCount = countIntersection(substantiveAiCategories, AI_TIER_B);
  const tierCCount = countIntersection(substantiveAiCategories, AI_TIER_C);

  const titleAiCategories = categories(aiTitleMatches);
  const skillAiCategories = categories(aiSkillMatches);
  const narrativeAiCategories = categories(aiNarrativeMatches);
  const implCategories = categories(allImplMatches);
  const genericCategories = categories(allGenericMatches);

  const incidentalOnly =
    incidentalMatches.length > 0 &&
    coreWorkMatches.length === 0 &&
    substantiveAiCategories.length <= 1 &&
    implCategories.length === 0;

  return {
    aiTitleMatches,
    aiSkillMatches,
    aiNarrativeMatches,
    allAiMatches,
    allAiCategories,
    substantiveAiCategories,
    titleAiCategories,
    skillAiCategories,
    narrativeAiCategories,

    implTitleMatches,
    implSkillMatches,
    implNarrativeMatches,
    allImplMatches,
    implCategories,

    allGenericMatches,
    genericCategories,

    coreWorkMatches,
    coreWorkCategories: categories(coreWorkMatches),
    incidentalMatches,
    incidentalCategories: categories(incidentalMatches),
    incidentalOnly,

    tierACount,
    tierBCount,
    tierCCount,
  };
}

function classifyRole(titleText) {
  const targetMatches = matchPatterns(targetRolePatterns, titleText);
  const adjacentMatches = matchPatterns(adjacentRolePatterns, titleText);
  const offTargetMatches = matchPatterns(offTargetRolePatterns, titleText);

  const targetTier = bestTier(targetMatches.map((match) => match.tier));
  const absoluteOffTarget = offTargetMatches.filter(
    (match) => match.severity === 'absolute'
  );
  const softOffTarget = offTargetMatches.filter(
    (match) => match.severity === 'soft'
  );
  const stackOffTarget = offTargetMatches.filter(
    (match) => match.severity === 'stack'
  );

  let roleClass = 'neutral';

  if (targetMatches.length > 0 && offTargetMatches.length > 0) {
    roleClass = 'mixed_target_off_target';
  } else if (targetMatches.length > 0) {
    roleClass = 'target';
  } else if (absoluteOffTarget.length > 0) {
    roleClass = 'absolute_off_target';
  } else if (softOffTarget.length > 0) {
    roleClass = 'soft_off_target';
  } else if (stackOffTarget.length > 0) {
    roleClass = 'stack_off_target';
  } else if (adjacentMatches.length > 0) {
    roleClass = 'adjacent';
  }

  return {
    roleClass,
    targetTier,
    targetMatches,
    adjacentMatches,
    offTargetMatches,
    absoluteOffTarget,
    softOffTarget,
    stackOffTarget,
  };
}

// ============================================================
// 9. PASS / REVIEW / REJECT DECISION ENGINE
// ============================================================

function decideVacancy(role, evidence) {
  const reasons = [];
  const warnings = [];
  const rejectionReasons = [];

  const substantiveCount = evidence.substantiveAiCategories.length;
  const implCount = evidence.implCategories.length;
  const coreWorkCount = evidence.coreWorkCategories.length;
  const titleSubstantiveCount = evidence.titleAiCategories.filter(
    (category) => category !== 'GENERAL_AI'
  ).length;
  const skillSubstantiveCount = evidence.skillAiCategories.filter(
    (category) => category !== 'GENERAL_AI'
  ).length;

  const topPriorityCount = evidence.tierACount + evidence.tierBCount;
  const denseAiEvidence =
    topPriorityCount >= 2 ||
    (topPriorityCount >= 1 && implCount >= 1) ||
    (substantiveCount >= 2 && implCount >= 1) ||
    implCount >= 2 ||
    coreWorkCount >= 1;

  // ----------------------------------------------------------
  // Hard rejects with high confidence
  // ----------------------------------------------------------

  if (
    role.roleClass === 'absolute_off_target' &&
    role.targetMatches.length === 0
  ) {
    rejectionReasons.push('absolute_off_target_role');
    return {
      decision: 'REJECT',
      code: 'reject_absolute_off_target_role',
      reasons,
      warnings,
      rejectionReasons,
    };
  }

  if (
    substantiveCount === 0 &&
    implCount === 0 &&
    coreWorkCount === 0
  ) {
    rejectionReasons.push('no_substantive_ai_evidence');
    return {
      decision: 'REJECT',
      code: 'reject_no_ai_evidence',
      reasons,
      warnings,
      rejectionReasons,
    };
  }

  if (
    evidence.incidentalOnly &&
    role.targetMatches.length === 0
  ) {
    rejectionReasons.push('ai_mentioned_only_incidentally');
    return {
      decision: 'REJECT',
      code: 'reject_incidental_ai_only',
      reasons,
      warnings,
      rejectionReasons,
    };
  }

  // ----------------------------------------------------------
  // Exact target roles
  // ----------------------------------------------------------

  if (role.targetMatches.length > 0) {
    reasons.push(`target_role_tier_${role.targetTier ?? 'unknown'}`);

    if (role.absoluteOffTarget.length > 0) {
      warnings.push('target_role_conflicts_with_absolute_off_target_role');
      return {
        decision: 'REVIEW',
        code: 'review_target_role_conflict',
        reasons,
        warnings,
        rejectionReasons,
      };
    }

    if (role.targetTier === 'A' || role.targetTier === 'B') {
      return {
        decision: 'PASS',
        code: 'pass_target_role',
        reasons,
        warnings,
        rejectionReasons,
      };
    }

    // Tier C is relevant, but less aligned with the user's primary profile.
    warnings.push('lower_profile_alignment_target_role');
    return {
      decision: 'REVIEW',
      code: 'review_tier_c_target_role',
      reasons,
      warnings,
      rejectionReasons,
    };
  }

  // ----------------------------------------------------------
  // Adjacent technical roles
  // ----------------------------------------------------------

  if (role.roleClass === 'adjacent') {
    if (
      coreWorkCount >= 1 &&
      substantiveCount >= 1
    ) {
      reasons.push('adjacent_role_with_explicit_core_ai_work');
      return {
        decision: 'PASS',
        code: 'pass_adjacent_with_core_ai_work',
        reasons,
        warnings,
        rejectionReasons,
      };
    }

    if (
      evidence.tierACount >= 2 ||
      (evidence.tierACount >= 1 && implCount >= 1) ||
      (topPriorityCount >= 2 && implCount >= 1)
    ) {
      reasons.push('adjacent_role_with_dense_high_priority_ai');
      return {
        decision: 'PASS',
        code: 'pass_adjacent_dense_ai',
        reasons,
        warnings,
        rejectionReasons,
      };
    }

    if (
      substantiveCount >= 1 &&
      (implCount >= 1 || skillSubstantiveCount >= 1 || titleSubstantiveCount >= 1)
    ) {
      warnings.push('adjacent_role_requires_full_page_validation');
      return {
        decision: 'REVIEW',
        code: 'review_adjacent_with_ai_evidence',
        reasons,
        warnings,
        rejectionReasons,
      };
    }

    rejectionReasons.push('adjacent_role_without_enough_ai_evidence');
    return {
      decision: 'REJECT',
      code: 'reject_adjacent_low_ai_evidence',
      reasons,
      warnings,
      rejectionReasons,
    };
  }

  // ----------------------------------------------------------
  // Soft off-target roles: analyst / consultant / DevOps
  // ----------------------------------------------------------

  if (role.roleClass === 'soft_off_target') {
    if (
      coreWorkCount >= 1 &&
      topPriorityCount >= 1 &&
      implCount >= 1
    ) {
      warnings.push('soft_off_target_role_but_core_ai_work_detected');
      return {
        decision: 'REVIEW',
        code: 'review_soft_off_target_with_core_ai',
        reasons,
        warnings,
        rejectionReasons,
      };
    }

    if (
      evidence.tierACount >= 2 &&
      implCount >= 2
    ) {
      warnings.push('soft_off_target_role_but_dense_ai_stack_detected');
      return {
        decision: 'REVIEW',
        code: 'review_soft_off_target_dense_ai',
        reasons,
        warnings,
        rejectionReasons,
      };
    }

    rejectionReasons.push('off_target_role_without_core_ai_work');
    return {
      decision: 'REJECT',
      code: 'reject_soft_off_target_low_ai_core',
      reasons,
      warnings,
      rejectionReasons,
    };
  }

  // ----------------------------------------------------------
  // Wrong technical stack roles: Frontend / QA / Mobile / etc.
  // ----------------------------------------------------------

  if (role.roleClass === 'stack_off_target') {
    if (
      coreWorkCount >= 1 &&
      evidence.tierACount >= 2 &&
      implCount >= 1
    ) {
      warnings.push('stack_off_target_role_but_strong_core_ai_work_detected');
      return {
        decision: 'REVIEW',
        code: 'review_stack_off_target_strong_ai',
        reasons,
        warnings,
        rejectionReasons,
      };
    }

    rejectionReasons.push('wrong_primary_technical_stack');
    return {
      decision: 'REJECT',
      code: 'reject_wrong_primary_stack',
      reasons,
      warnings,
      rejectionReasons,
    };
  }

  // ----------------------------------------------------------
  // Neutral / unconventional titles
  // ----------------------------------------------------------

  if (coreWorkCount >= 1 && topPriorityCount >= 1) {
    reasons.push('unconventional_title_with_explicit_core_ai_work');
    return {
      decision: 'PASS',
      code: 'pass_neutral_core_ai_work',
      reasons,
      warnings,
      rejectionReasons,
    };
  }

  if (
    evidence.tierACount >= 2 ||
    (topPriorityCount >= 2 && implCount >= 1) ||
    (substantiveCount >= 2 && implCount >= 2)
  ) {
    warnings.push('unconventional_title_with_dense_ai_evidence');
    return {
      decision: 'REVIEW',
      code: 'review_neutral_dense_ai',
      reasons,
      warnings,
      rejectionReasons,
    };
  }

  if (
    denseAiEvidence &&
    (titleSubstantiveCount >= 1 || skillSubstantiveCount >= 1)
  ) {
    warnings.push('ambiguous_role_but_ai_evidence_present');
    return {
      decision: 'REVIEW',
      code: 'review_ambiguous_ai_role',
      reasons,
      warnings,
      rejectionReasons,
    };
  }

  rejectionReasons.push('insufficient_ai_relevance');
  return {
    decision: 'REJECT',
    code: 'reject_insufficient_ai_relevance',
    reasons,
    warnings,
    rejectionReasons,
  };
}

// ============================================================
// 10. TRANSPARENT PRIORITY SCORE
// ============================================================

/**
 * Score is ONLY for ordering/prioritization.
 * PASS/REVIEW/REJECT is decided by explicit rules above.
 */
function calculatePriorityScore(role, evidence, seniority, workFormat, geo) {
  let score = 0;

  // Role alignment
  if (role.targetTier === 'A') score += 42;
  else if (role.targetTier === 'B') score += 34;
  else if (role.targetTier === 'C') score += 22;
  else if (role.roleClass === 'adjacent') score += 12;
  else if (role.roleClass === 'soft_off_target') score -= 10;
  else if (role.roleClass === 'stack_off_target') score -= 20;
  else if (role.roleClass === 'absolute_off_target') score -= 50;

  // AI domains, capped by category count
  score += Math.min(evidence.tierACount, 3) * 12;
  score += Math.min(evidence.tierBCount, 3) * 7;
  score += Math.min(evidence.tierCCount, 3) * 4;

  // Source quality of evidence
  const titleSubstantive = evidence.titleAiCategories.filter(
    (category) => category !== 'GENERAL_AI'
  ).length;
  const skillSubstantive = evidence.skillAiCategories.filter(
    (category) => category !== 'GENERAL_AI'
  ).length;

  score += Math.min(titleSubstantive, 2) * 7;
  score += Math.min(skillSubstantive, 3) * 5;
  score += Math.min(evidence.implCategories.length, 4) * 5;
  score += Math.min(evidence.coreWorkCategories.length, 2) * 12;

  // Generic tech only supports, never dominates
  score += Math.min(evidence.genericCategories.length, 4) * 1;

  // Incidental AI mention penalty
  score -= Math.min(evidence.incidentalCategories.length, 2) * 6;

  // Work-format preference
  if (workFormat.hint === 'remote' && !workFormat.remote_denied_signal) score += 5;
  if (geo.tbilisi_signal) score += 5;

  // Seniority lowers ordering priority, but does not reject here.
  if (seniority.risk === 'medium') score -= 4;
  if (seniority.risk === 'high') score -= 10;

  return clamp(Math.round(score), 0, 100);
}

function scoreToPriority(score) {
  if (score >= 80) return 'very_high';
  if (score >= 60) return 'high';
  if (score >= 40) return 'medium';
  return 'low';
}

function scoreToConfidence(decision, role, evidence) {
  if (decision === 'REJECT') {
    if (
      role.roleClass === 'absolute_off_target' ||
      (evidence.substantiveAiCategories.length === 0 &&
        evidence.implCategories.length === 0)
    ) {
      return 'high';
    }
    return 'medium';
  }

  if (
    role.targetTier === 'A' ||
    evidence.coreWorkCategories.length >= 1 ||
    evidence.tierACount >= 2
  ) {
    return 'high';
  }

  return decision === 'PASS' ? 'medium' : 'low';
}

// ============================================================
// 11. MAIN LOOP
// ============================================================

const result = [];

for (let inputIndex = 0; inputIndex < items.length; inputIndex++) {
  const item = items[inputIndex];
  const parsed = parseHabrRss(item.json);

  const titleText = parsed.vacancy_title_normalized;
  const allText = [
    parsed.vacancy_title_normalized,
    parsed.rss_skills_text,
    parsed.rss_narrative_text,
    parsed.rss_full_text,
  ]
    .filter(Boolean)
    .join(' ');

  const role = classifyRole(titleText);
  const evidence = collectAiEvidence(parsed);
  const seniority = classifySeniority(titleText, allText);
  const workFormat = classifyWorkFormat(allText);
  const geo = classifyGeoPolicy(workFormat, allText);
  const decision = decideVacancy(role, evidence);

  const score = calculatePriorityScore(
    role,
    evidence,
    seniority,
    workFormat,
    geo
  );

  const priority = scoreToPriority(score);
  const confidence = scoreToConfidence(
    decision.decision,
    role,
    evidence
  );

  const shouldFetchFullPage = decision.decision !== 'REJECT';

  const diagnosticReasons = [];

  if (role.targetMatches.length) {
    diagnosticReasons.push(`target roles: ${names(role.targetMatches).join(', ')}`);
  }
  if (role.adjacentMatches.length) {
    diagnosticReasons.push(`adjacent roles: ${names(role.adjacentMatches).join(', ')}`);
  }
  if (role.offTargetMatches.length) {
    diagnosticReasons.push(`off-target warnings: ${names(role.offTargetMatches).join(', ')}`);
  }
  if (evidence.substantiveAiCategories.length) {
    diagnosticReasons.push(`AI categories: ${evidence.substantiveAiCategories.join(', ')}`);
  }
  if (evidence.implCategories.length) {
    diagnosticReasons.push(`AI implementation: ${evidence.implCategories.join(', ')}`);
  }
  if (evidence.coreWorkCategories.length) {
    diagnosticReasons.push(`core AI work: ${evidence.coreWorkCategories.join(', ')}`);
  }
  if (evidence.incidentalCategories.length) {
    diagnosticReasons.push(`incidental AI hints: ${evidence.incidentalCategories.join(', ')}`);
  }

  result.push({
    pairedItem: { item: inputIndex },
    json: {
      ...item.json,

      // ---------------- Pre-filter decision ----------------
      prefilter_version: PREFILTER_VERSION,
      prefilter_decision: decision.decision,
      prefilter_decision_code: decision.code,
      prefilter_passed: shouldFetchFullPage,
      should_fetch_full_page: shouldFetchFullPage,
      prefilter_score: score,
      prefilter_priority: priority,
      relevance_confidence: confidence,
      prefilter_reasons: uniq([
        ...decision.reasons,
        ...diagnosticReasons,
      ]),
      prefilter_warnings: uniq(decision.warnings),
      prefilter_rejection_reasons: uniq(decision.rejectionReasons),

      // ---------------- Parsed Habr RSS ----------------
      rss_parsed_vacancy_title: parsed.vacancy_title_raw,
      rss_parsed_skills: parsed.rss_skills,
      normalized_title: parsed.vacancy_title_normalized,

      // ---------------- Role classification ----------------
      title_role_class: role.roleClass,
      target_role_tier: role.targetTier,
      matched_target_roles: names(role.targetMatches),
      matched_adjacent_roles: names(role.adjacentMatches),
      matched_off_target_roles: names(role.offTargetMatches),
      matched_absolute_off_target_roles: names(role.absoluteOffTarget),
      matched_soft_off_target_roles: names(role.softOffTarget),
      matched_stack_off_target_roles: names(role.stackOffTarget),

      // ---------------- AI evidence by source ----------------
      matched_ai_categories_title: evidence.titleAiCategories,
      matched_ai_categories_skills: evidence.skillAiCategories,
      matched_ai_categories_narrative: evidence.narrativeAiCategories,
      matched_ai_categories_all: evidence.allAiCategories,
      matched_substantive_ai_categories: evidence.substantiveAiCategories,

      matched_ai_signals_title: names(evidence.aiTitleMatches),
      matched_ai_signals_skills: names(evidence.aiSkillMatches),
      matched_ai_signals_narrative: names(evidence.aiNarrativeMatches),

      matched_ai_implementation_signals: names(evidence.allImplMatches),
      matched_ai_implementation_categories: evidence.implCategories,
      matched_generic_tech_signals: names(evidence.allGenericMatches),

      matched_core_ai_work_signals: names(evidence.coreWorkMatches),
      matched_core_ai_work_categories: evidence.coreWorkCategories,
      matched_incidental_ai_signals: names(evidence.incidentalMatches),
      matched_incidental_ai_categories: evidence.incidentalCategories,
      incidental_ai_only: evidence.incidentalOnly,

      ai_priority_tier_a_count: evidence.tierACount,
      ai_priority_tier_b_count: evidence.tierBCount,
      ai_priority_tier_c_count: evidence.tierCCount,

      // ---------------- Seniority ----------------
      matched_level_signals: seniority.level_matches,
      matched_level_categories: seniority.level_categories,
      experience_min_years_hint: seniority.experience_min_years_hint,
      experience_max_years_hint: seniority.experience_max_years_hint,
      matched_experience_signals: seniority.experience_matches,
      seniority_risk_hint: seniority.risk,

      // ---------------- Work format ----------------
      work_format_hint: workFormat.hint,
      work_format_confidence: workFormat.confidence,
      work_format_source: 'rss_text',
      work_format_conflict: workFormat.conflict,
      remote_signal: workFormat.remote_signal,
      hybrid_signal: workFormat.hybrid_signal,
      office_signal: workFormat.office_signal,
      remote_denied_signal: workFormat.remote_denied_signal,

      // ---------------- Geography ----------------
      tbilisi_signal: geo.tbilisi_signal,
      georgia_signal: geo.georgia_signal,
      geo_format_policy: geo.policy,
      needs_full_page_geo_check: geo.needs_full_page_geo_check,

      // Salary is intentionally not used anywhere in this pre-filter.
      salary_filter_applied: false,
    },
  });
}

// PASS first, then REVIEW, then REJECT.
// Within a decision bucket: highest score first, then newest vacancy.
result.sort((a, b) => {
  const decisionDiff =
    decisionRank(a.json.prefilter_decision) -
    decisionRank(b.json.prefilter_decision);

  if (decisionDiff !== 0) return decisionDiff;

  const scoreDiff =
    (b.json.prefilter_score ?? 0) -
    (a.json.prefilter_score ?? 0);

  if (scoreDiff !== 0) return scoreDiff;

  const aDate = Date.parse(a.json.isoDate ?? a.json.pubDate ?? '') || 0;
  const bDate = Date.parse(b.json.isoDate ?? b.json.pubDate ?? '') || 0;

  return bDate - aDate;
});

return result;

/**
 * MARK — Habr Career Vacancy Normalizer
 * Version: 1.0.0
 *
 * n8n Code node mode: Run Once for Each Item
 *
 * Expected input:
 *   $json.data — HTML returned by "Fetch Habr Vacancy Page"
 *
 * Data priority:
 *   1. Habr SSR state
 *   2. JSON-LD JobPosting
 *   3. Linked RSS metadata (diagnostic fallback only)
 *
 * Important policies:
 *   - the node normalizes; it does not reject vacancies;
 *   - employer salary and Habr predicted salary never mix;
 *   - missing salary is not an error;
 *   - remoteWork === false does not mean office;
 *   - one malformed page returns diagnostics instead of failing the batch;
 *   - raw page HTML is never included in the output.
 */

const NORMALIZER_VERSION = '1.0.0';
const SCHEMA_VERSION = 'mark.vacancy.v1';
const HABR_BASE_URL = 'https://career.habr.com';

const errors = [];
const warnings = [];

function isPresent(value) {
  return value !== null &&
    value !== undefined &&
    !(typeof value === 'string' && value.trim() === '');
}

function firstPresent(...values) {
  for (const value of values) {
    if (isPresent(value)) return value;
  }

  return null;
}

function asObject(value) {
  return value && typeof value === 'object' && !Array.isArray(value)
    ? value
    : {};
}

function toText(value) {
  if (!isPresent(value)) return null;

  if (typeof value === 'string') {
    const result = value.trim();
    return result || null;
  }

  if (typeof value === 'number' || typeof value === 'boolean') {
    return String(value);
  }

  if (Array.isArray(value)) {
    const result = value.map(toText).filter(Boolean).join(', ');
    return result || null;
  }

  if (typeof value === 'object') {
    return toText(firstPresent(
      value.title,
      value.name,
      value.label,
      value.text,
      value.value,
      value.code,
    ));
  }

  return null;
}

function uniqueStrings(values) {
  const result = [];
  const seen = new Set();

  for (const value of values.flat(Infinity)) {
    const text = toText(value);
    if (!text) continue;

    const key = text.toLocaleLowerCase('ru-RU');
    if (seen.has(key)) continue;

    seen.add(key);
    result.push(text);
  }

  return result;
}

function decodeHtmlEntities(value) {
  const named = {
    amp: '&',
    apos: "'",
    quot: '"',
    lt: '<',
    gt: '>',
    nbsp: ' ',
    ndash: '–',
    mdash: '—',
    hellip: '…',
    laquo: '«',
    raquo: '»',
    bull: '•',
  };

  return String(value ?? '')
    .replace(/&#(?:x([0-9a-f]+)|(\d+));/gi, (match, hex, decimal) => {
      const codePoint = hex
        ? Number.parseInt(hex, 16)
        : Number.parseInt(decimal, 10);

      if (!Number.isFinite(codePoint) || codePoint < 0 || codePoint > 0x10FFFF) {
        return match;
      }

      try {
        return String.fromCodePoint(codePoint);
      } catch {
        return match;
      }
    })
    .replace(/&([a-z]+);/gi, (match, name) =>
      named[name.toLowerCase()] ?? match,
    );
}

function htmlToText(value) {
  if (!isPresent(value)) return '';

  return decodeHtmlEntities(
    String(value)
      .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/gi, '$1')
      .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, ' ')
      .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, ' ')
      .replace(/<noscript\b[^>]*>[\s\S]*?<\/noscript>/gi, ' ')
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<li\b[^>]*>/gi, '\n• ')
      .replace(/<\/li>/gi, '\n')
      .replace(
        /<\/(?:p|div|section|article|header|footer|h[1-6]|ul|ol|table|tr)>/gi,
        '\n',
      )
      .replace(/<[^>]+>/g, ' '),
  )
    .replace(/\u00a0/g, ' ')
    .replace(/\r/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function normalizeSearchText(value) {
  return String(value ?? '')
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/[–—−]/g, '-')
    .replace(/\s+/g, ' ')
    .trim();
}

function safeJsonParse(value) {
  if (!isPresent(value)) return null;

  let text = String(value)
    .trim()
    .replace(/^<!--/, '')
    .replace(/-->$/, '')
    .replace(/;$/, '')
    .trim();

  const attempts = [text, decodeHtmlEntities(text)];

  for (const attempt of attempts) {
    try {
      let parsed = JSON.parse(attempt);

      if (typeof parsed === 'string') {
        parsed = JSON.parse(parsed);
      }

      return parsed;
    } catch {
      // Try the next representation.
    }
  }

  if (/^JSON\.parse\s*\(/i.test(text) && text.endsWith(')')) {
    const argument = text.slice(text.indexOf('(') + 1, -1).trim();

    try {
      const decoded = JSON.parse(argument);
      return typeof decoded === 'string'
        ? JSON.parse(decoded)
        : decoded;
    } catch {
      return null;
    }
  }

  return null;
}

function scriptBlocks(html) {
  if (!html) return [];

  const blocks = [];
  const regex = /<script\b([^>]*)>([\s\S]*?)<\/script>/gi;
  let match;

  while ((match = regex.exec(html)) !== null) {
    blocks.push({
      attributes: match[1] ?? '',
      content: match[2] ?? '',
    });
  }

  return blocks;
}

function extractSsrStates(html) {
  const states = [];

  for (const block of scriptBlocks(html)) {
    if (!/\bdata-ssr-state(?:\s*=\s*(?:["']?true["']?))?/i.test(block.attributes)) {
      continue;
    }

    const parsed = safeJsonParse(block.content);
    if (parsed && typeof parsed === 'object') {
      states.push(parsed);
    } else {
      warnings.push('habr_ssr_state_parse_failed');
    }
  }

  if (states.length === 0) {
    warnings.push('habr_ssr_state_not_found');
  }

  return states;
}

function extractVacancyId(...values) {
  for (const value of values) {
    const text = toText(value);
    if (!text) continue;

    const urlMatch = text.match(/\/vacancies\/(\d+)/i);
    if (urlMatch) return urlMatch[1];

    if (/^\d{6,}$/.test(text)) return text;

    const longNumber = text.match(/(?:^|\D)(\d{6,})(?:\D|$)/);
    if (longNumber) return longNumber[1];
  }

  return null;
}

function findVacancyObject(states, expectedId) {
  let best = null;
  let bestScore = -1;
  const seen = new Set();

  function inspect(value, path, depth) {
    if (!value || typeof value !== 'object' || depth > 10 || seen.has(value)) {
      return;
    }

    seen.add(value);

    if (!Array.isArray(value)) {
      const objectId = extractVacancyId(value.id, value.href, value.url);
      const hasTitle = isPresent(value.title);
      const hasDescription = isPresent(value.description);
      const hasCompany = isPresent(value.company);

      if (hasTitle && hasDescription && (hasCompany || objectId)) {
        let score = 0;

        if (expectedId && objectId === expectedId) score += 30;
        if (/\.vacancy$|^vacancy$/i.test(path)) score += 10;
        if (objectId) score += 3;
        if (hasTitle) score += 3;
        if (hasDescription) score += 6;
        if (hasCompany) score += 3;
        if (Array.isArray(value.skills)) score += 2;
        if (Object.prototype.hasOwnProperty.call(value, 'remoteWork')) score += 2;
        if (Object.prototype.hasOwnProperty.call(value, 'predictedSalary')) score += 2;

        if (score > bestScore) {
          best = value;
          bestScore = score;
        }
      }
    }

    const entries = Array.isArray(value)
      ? value.slice(0, 250).map((item, index) => [String(index), item])
      : Object.entries(value).slice(0, 250);

    for (const [key, child] of entries) {
      if (child && typeof child === 'object') {
        inspect(child, path ? `${path}.${key}` : key, depth + 1);
      }
    }
  }

  for (const state of states) {
    inspect(state, '', 0);
  }

  return best;
}

function hasSchemaType(value, expectedType) {
  const types = Array.isArray(value) ? value : [value];

  return types.some((type) =>
    String(type ?? '').toLowerCase() === expectedType.toLowerCase(),
  );
}

function findJobPosting(value, depth = 0) {
  if (!value || depth > 10) return null;

  if (Array.isArray(value)) {
    for (const item of value) {
      const found = findJobPosting(item, depth + 1);
      if (found) return found;
    }

    return null;
  }

  if (typeof value !== 'object') return null;

  if (hasSchemaType(value['@type'], 'JobPosting')) {
    return value;
  }

  for (const child of Object.values(value)) {
    if (child && typeof child === 'object') {
      const found = findJobPosting(child, depth + 1);
      if (found) return found;
    }
  }

  return null;
}

function extractJsonLdJobPosting(html) {
  for (const block of scriptBlocks(html)) {
    if (!/\btype\s*=\s*["']application\/ld\+json["']/i.test(block.attributes)) {
      continue;
    }

    const parsed = safeJsonParse(block.content);
    if (!parsed) continue;

    const found = findJobPosting(parsed);
    if (found) return found;
  }

  warnings.push('job_posting_json_ld_not_found');
  return null;
}

function absoluteUrl(value) {
  const text = toText(value);
  if (!text) return null;

  try {
    return new URL(text, HABR_BASE_URL).href;
  } catch {
    return text;
  }
}

function normalizeDate(value) {
  const text = toText(
    value && typeof value === 'object'
      ? firstPresent(value.date, value.iso, value.isoDate, value.value, value.formatted)
      : value,
  );

  if (!text) return null;

  const timestamp = Date.parse(text);
  return Number.isNaN(timestamp)
    ? text
    : new Date(timestamp).toISOString();
}

function parseNumber(value) {
  if (typeof value === 'number') {
    return Number.isFinite(value) ? value : null;
  }

  const text = toText(value);
  if (!text) return null;

  const match = text
    .replace(/[\s\u00a0]+/g, '')
    .replace(',', '.')
    .match(/-?\d+(?:\.\d+)?/);

  if (!match) return null;

  const result = Number(match[0]);
  return Number.isFinite(result) ? result : null;
}

function normalizeCurrency(value) {
  const text = toText(value);
  if (!text) return null;

  const normalized = text.toUpperCase();
  const aliases = {
    '₽': 'RUR',
    RUB: 'RUR',
    RUR: 'RUR',
    '$': 'USD',
    USD: 'USD',
    '€': 'EUR',
    EUR: 'EUR',
    '₾': 'GEL',
    GEL: 'GEL',
  };

  return aliases[normalized] ?? normalized;
}

function normalizeSalary(rawSalary, jsonLdSalary = null) {
  const raw = asObject(rawSalary);
  const ld = asObject(jsonLdSalary);
  const ldValue = asObject(ld.value);

  const exactValue = parseNumber(firstPresent(
    raw.value,
    ldValue.value,
    typeof ld.value === 'number' ? ld.value : null,
  ));

  let from = parseNumber(firstPresent(
    raw.from,
    raw.min,
    raw.minValue,
    ldValue.minValue,
    ld.minValue,
  ));

  let to = parseNumber(firstPresent(
    raw.to,
    raw.max,
    raw.maxValue,
    ldValue.maxValue,
    ld.maxValue,
  ));

  if (exactValue !== null) {
    if (from === null) from = exactValue;
    if (to === null) to = exactValue;
  }

  const formatted = toText(firstPresent(raw.formatted, raw.display, raw.text));

  return {
    from,
    to,
    currency: normalizeCurrency(firstPresent(
      raw.currency,
      raw.currencyCode,
      ld.currency,
      ldValue.currency,
    )),
    formatted,
    period: toText(firstPresent(raw.period, raw.unit, ldValue.unitText, ld.unitText)),
    specified: from !== null || to !== null || Boolean(formatted),
  };
}

function labelsFrom(value) {
  if (!isPresent(value)) return [];

  const values = Array.isArray(value) ? value : [value];

  return uniqueStrings(values.map((item) =>
    typeof item === 'string'
      ? item
      : firstPresent(item?.title, item?.name, item?.label, item?.value),
  ));
}

function splitSkillText(value) {
  if (!isPresent(value)) return [];

  if (Array.isArray(value)) {
    return uniqueStrings(value.flatMap(splitSkillText));
  }

  if (typeof value === 'object') return labelsFrom(value);

  return uniqueStrings(
    String(value)
      .replace(/#/g, '')
      .split(/[,;\n|]+/)
      .map((item) => item.trim()),
  );
}

function collectLocationData(value, accumulator) {
  if (!isPresent(value)) return;

  if (Array.isArray(value)) {
    for (const item of value) collectLocationData(item, accumulator);
    return;
  }

  if (typeof value === 'string') {
    accumulator.labels.push(value);
    return;
  }

  if (typeof value !== 'object') return;

  const label = toText(firstPresent(value.title, value.name, value.label, value.value));
  if (label) accumulator.labels.push(label);

  const city = toText(firstPresent(
    value.city?.title,
    value.city?.name,
    value.city,
    value.addressLocality,
    value.locality,
  ));
  if (city) accumulator.cities.push(city);

  const country = toText(firstPresent(
    value.country?.title,
    value.country?.name,
    value.country?.code,
    value.country,
    value.addressCountry?.name,
    value.addressCountry?.code,
    value.addressCountry,
  ));
  if (country) accumulator.countries.push(country);

  if (value.address) collectLocationData(value.address, accumulator);
}

function detectGeography(accumulator, humanCityNames, shortGeo) {
  const labels = uniqueStrings([
    accumulator.labels,
    humanCityNames,
    shortGeo,
  ]);
  const cities = uniqueStrings(accumulator.cities);
  const countries = uniqueStrings(accumulator.countries);
  const text = uniqueStrings([labels, cities, countries]).join(' ');

  const isTbilisi = /(?:^|[^\p{L}])(?:тбилиси|tbilisi|თბილისი)(?=$|[^\p{L}])/iu.test(text);
  const explicitGeorgia = /(?:^|[^\p{L}])(?:грузи(?:я|и)|საქართველო)(?=$|[^\p{L}])/iu.test(text);
  const englishGeorgia = /(?:^|[^\p{L}])georgia(?=$|[^\p{L}])/iu.test(text);
  const looksLikeUsGeorgia = /\b(?:usa|u\.s\.a|united states|georgia,\s*ga|ga,\s*usa|atlanta)\b/i.test(text);
  const isGeorgia = isTbilisi || explicitGeorgia || (englishGeorgia && !looksLikeUsGeorgia);
  const isRussia = /(?:^|[^\p{L}])(?:росси(?:я|и)|russia|russian federation)(?=$|[^\p{L}])/iu.test(text);

  let city = cities[0] ?? null;
  let country = countries[0] ?? null;

  if (!city && isPresent(humanCityNames)) {
    city = String(humanCityNames).split(/[,()]/)[0]?.trim() || null;
  }

  if (!city && labels.length) {
    city = labels[0].split(/[,()]/)[0]?.trim() || null;
  }

  if (isTbilisi) city = 'Tbilisi';
  if (isGeorgia) country = 'Georgia';
  else if (isRussia) country = 'Russia';

  return {
    location: firstPresent(toText(humanCityNames), toText(shortGeo), labels.join(', ')),
    locations: labels,
    short_geo: toText(shortGeo),
    city,
    country,
    is_tbilisi: isTbilisi,
    is_georgia: isGeorgia,
  };
}

function matchesAny(patterns, text) {
  return patterns.some((pattern) => pattern.test(text));
}

function detectWorkSignals(value) {
  const text = normalizeSearchText(value);

  const remotePatterns = [
    /полност\p{L}*\s+(?:удален|дистанцион)/u,
    /можно\s+(?:работать\s+)?удален/u,
    /удаленн\p{L}*\s+(?:работ|формат|позици)/u,
    /работ\p{L}*\s+удален/u,
    /дистанционн\p{L}*\s+(?:работ|формат)/u,
    /\bfully[\s-]*remote\b/i,
    /\bfull[\s-]*remote\b/i,
    /\bremote[\s-]*first\b/i,
    /\bwork[\s-]*from[\s-]*anywhere\b/i,
    /\bremote\b/i,
  ];

  const hybridPatterns = [
    /гибрид/u,
    /частичн\p{L}*\s+(?:удален|дистанцион)/u,
    /\bhybrid\b/i,
    /\d+\s+дн\p{L}*\s+в\s+офис/u,
    /несколько\s+дн\p{L}*\s+в\s+офис/u,
  ];

  const officePatterns = [
    /только\s+офис/u,
    /исключительн\p{L}*\s+(?:из|в)\s+офис/u,
    /работ\p{L}*\s+(?:из|в)\s+офис/u,
    /офисн\p{L}*\s+(?:формат|работ|график)/u,
    /обязательн\p{L}*\s+посещен\p{L}*\s+офис/u,
    /\b(?:on[\s-]*site|onsite)\b/i,
    /\boffice[\s-]*based\b/i,
  ];

  const deniedPatterns = [
    /удаленн\p{L}*\s+работ\p{L}*\s+не\s+предусмотр/u,
    /удаленк\p{L}*\s+не\s+предусмотр/u,
    /без\s+возможност\p{L}*\s+(?:работать\s+)?удален/u,
    /нет\s+возможност\p{L}*\s+(?:работать\s+)?удален/u,
    /только\s+офис/u,
    /исключительн\p{L}*\s+(?:из|в)\s+офис/u,
    /\bno[\s-]*remote\b/i,
    /\bremote\s+(?:is\s+)?not\s+available\b/i,
  ];

  return {
    remote: matchesAny(remotePatterns, text),
    hybrid: matchesAny(hybridPatterns, text),
    office: matchesAny(officePatterns, text),
    remote_denied: matchesAny(deniedPatterns, text),
  };
}

function detectWorkFormat({ structuredRemote, jsonLdRemote, fullText, rssText, source }) {
  const full = detectWorkSignals(fullText);
  const rss = detectWorkSignals(rssText);
  const rssHint = ['remote', 'hybrid', 'office'].includes(source.work_format_hint)
    ? source.work_format_hint
    : null;

  const evidence = [];
  if (structuredRemote) evidence.push('habr.remoteWork=true');
  if (jsonLdRemote) evidence.push('jsonld.jobLocationType=TELECOMMUTE');
  for (const [name, matched] of Object.entries(full)) {
    if (matched) evidence.push(`full_description:${name}`);
  }
  if (rssHint) evidence.push(`rss_hint:${rssHint}`);

  let workFormat = 'unknown';
  let confidence = 'low';
  let formatSource = 'unknown';

  if (structuredRemote || jsonLdRemote) {
    workFormat = 'remote';
    confidence = 'high';
    formatSource = 'structured_data';
  } else if (full.hybrid) {
    workFormat = 'hybrid';
    confidence = 'high';
    formatSource = 'full_description';
  } else if (full.remote && !full.remote_denied) {
    workFormat = 'remote';
    confidence = 'high';
    formatSource = 'full_description';
  } else if (full.office) {
    workFormat = 'office';
    confidence = 'high';
    formatSource = 'full_description';
  } else if (rssHint) {
    workFormat = rssHint;
    confidence = ['high', 'medium', 'low'].includes(source.work_format_confidence)
      ? source.work_format_confidence
      : 'medium';
    formatSource = 'rss_text';
  } else if (rss.hybrid) {
    workFormat = 'hybrid';
    confidence = 'medium';
    formatSource = 'rss_text';
  } else if (rss.remote && !rss.remote_denied) {
    workFormat = 'remote';
    confidence = 'medium';
    formatSource = 'rss_text';
  } else if (rss.office) {
    workFormat = 'office';
    confidence = 'medium';
    formatSource = 'rss_text';
  }

  const conflict = Boolean(source.work_format_conflict) ||
    ((structuredRemote || jsonLdRemote) && (full.hybrid || full.office || full.remote_denied)) ||
    (full.remote && (full.hybrid || full.office || full.remote_denied)) ||
    (rss.remote && (rss.hybrid || rss.office || rss.remote_denied));

  if (conflict) warnings.push('work_format_conflict_detected');
  if (workFormat === 'unknown') warnings.push('work_format_unknown');

  return {
    work_format: workFormat,
    work_format_confidence: confidence,
    work_format_source: formatSource,
    work_format_conflict: conflict,
    work_format_evidence: uniqueStrings(evidence),
    remote_allowed_by_source: Boolean(structuredRemote || jsonLdRemote),
    remote_denied: Boolean(full.remote_denied || rss.remote_denied),
  };
}

function geoPolicyHint(workFormat, geography) {
  if (workFormat.work_format_conflict) return 'needs_review_conflict';
  if (workFormat.work_format === 'remote') return 'allow_remote';

  if (['hybrid', 'office'].includes(workFormat.work_format)) {
    return geography.is_tbilisi && geography.is_georgia
      ? 'allow_tbilisi'
      : 'reject_non_tbilisi';
  }

  return 'needs_review';
}

function sanitizeDiagnosticValue(value, depth = 0) {
  if (depth > 3) return null;

  if (value === null || ['string', 'number', 'boolean'].includes(typeof value)) {
    return value;
  }

  if (Array.isArray(value)) {
    return value.slice(0, 100).map((item) =>
      sanitizeDiagnosticValue(item, depth + 1),
    );
  }

  if (typeof value === 'object') {
    const output = {};
    for (const [key, item] of Object.entries(value).slice(0, 100)) {
      output[key] = sanitizeDiagnosticValue(item, depth + 1);
    }
    return output;
  }

  return null;
}

function collectPrefilterDiagnostics(source) {
  const diagnostics = {};
  const prefixes = [/^prefilter_/, /^matched_/, /^ai_priority_/, /^rss_parsed_/];
  const explicitKeys = new Set([
    'should_fetch_full_page',
    'relevance_confidence',
    'normalized_title',
    'title_role_class',
    'target_role_tier',
    'incidental_ai_only',
    'experience_min_years_hint',
    'experience_max_years_hint',
    'seniority_risk_hint',
    'salary_filter_applied',
  ]);

  for (const [key, value] of Object.entries(source ?? {})) {
    if (explicitKeys.has(key) || prefixes.some((pattern) => pattern.test(key))) {
      diagnostics[key] = sanitizeDiagnosticValue(value);
    }
  }

  diagnostics.rss_work_format_hint = source.work_format_hint ?? null;
  diagnostics.rss_work_format_confidence = source.work_format_confidence ?? null;
  diagnostics.rss_work_format_source = source.work_format_source ?? null;
  diagnostics.rss_work_format_conflict = source.work_format_conflict ?? false;
  diagnostics.rss_remote_signal = source.remote_signal ?? false;
  diagnostics.rss_hybrid_signal = source.hybrid_signal ?? false;
  diagnostics.rss_office_signal = source.office_signal ?? false;
  diagnostics.rss_remote_denied_signal = source.remote_denied_signal ?? false;
  diagnostics.rss_tbilisi_signal = source.tbilisi_signal ?? false;
  diagnostics.rss_georgia_signal = source.georgia_signal ?? false;
  diagnostics.rss_geo_format_policy = source.geo_format_policy ?? null;

  return diagnostics;
}

function getLinkedSource(current) {
  const currentMetadata = {};

  for (const [key, value] of Object.entries(current ?? {})) {
    if (!['data', 'body', 'html', 'response'].includes(key)) {
      currentMetadata[key] = value;
    }
  }

  const nodeNames = ['Dev Limit', 'Keep PASS + REVIEW', 'Habr RSS Pre-filter'];
  let linked = {};

  for (const nodeName of nodeNames) {
    try {
      const candidate = $(nodeName).item.json;
      if (candidate && typeof candidate === 'object') {
        linked = candidate;
        break;
      }
    } catch {
      // Try the next linked node.
    }
  }

  if (Object.keys(linked).length === 0 && Object.keys(currentMetadata).length === 0) {
    warnings.push('linked_rss_source_not_found');
  }

  return { ...linked, ...currentMetadata };
}

function getHtml(current) {
  const candidates = [
    current.data,
    current.body,
    current.html,
    current.response?.body,
    typeof current.response === 'string' ? current.response : null,
  ];

  return candidates.find((value) =>
    typeof value === 'string' && value.trim().length > 100,
  ) ?? '';
}

const inputItem = $input.item;
const current = asObject(inputItem?.json);
const source = getLinkedSource(current);

try {
  const html = getHtml(current);
  if (!html) warnings.push('vacancy_page_html_missing');

  const expectedId = extractVacancyId(source.guid, source.link, current.url, current.link);
  const ssrStates = extractSsrStates(html);
  const vacancy = findVacancyObject(ssrStates, expectedId);
  const jobPosting = extractJsonLdJobPosting(html);

  if (!vacancy) warnings.push('habr_ssr_vacancy_not_found');

  const rssDescription = htmlToText(firstPresent(source.content, source.contentSnippet));
  const description = firstPresent(
    htmlToText(vacancy?.description),
    htmlToText(jobPosting?.description),
    rssDescription,
  ) ?? '';
  const qualification = firstPresent(
    htmlToText(vacancy?.qualification),
    htmlToText(jobPosting?.qualifications),
    '',
  );
  const bannerDescription = htmlToText(vacancy?.bannerDescription);

  const sourceId = extractVacancyId(
    vacancy?.id,
    vacancy?.href,
    jobPosting?.identifier?.value,
    jobPosting?.identifier,
    expectedId,
  );
  const url = absoluteUrl(firstPresent(
    vacancy?.href,
    jobPosting?.url,
    source.link,
    sourceId ? `/vacancies/${sourceId}` : null,
  ));
  const title = toText(firstPresent(
    vacancy?.title,
    jobPosting?.title,
    source.rss_parsed_vacancy_title,
    source.title,
  ));

  const companyData = asObject(firstPresent(
    vacancy?.company,
    ssrStates.find((state) => isPresent(state?.company))?.company,
    jobPosting?.hiringOrganization,
  ));
  const company = toText(firstPresent(
    companyData.title,
    companyData.name,
    source.creator,
    source.author,
  ));

  const skills = uniqueStrings([
    labelsFrom(vacancy?.skills),
    splitSkillText(jobPosting?.skills),
    splitSkillText(source.rss_parsed_skills),
  ]);
  const specializations = uniqueStrings([
    labelsFrom(vacancy?.divisions),
    labelsFrom(vacancy?.specializations),
    splitSkillText(jobPosting?.occupationalCategory),
  ]);

  const locationAccumulator = { labels: [], cities: [], countries: [] };
  collectLocationData(vacancy?.locations, locationAccumulator);
  collectLocationData(vacancy?.location, locationAccumulator);
  collectLocationData(jobPosting?.jobLocation, locationAccumulator);

  const geography = detectGeography(
    locationAccumulator,
    toText(vacancy?.humanCityNames),
    toText(vacancy?.shortGeo),
  );

  const fullDescriptionText = uniqueStrings([
    description,
    qualification,
    bannerDescription,
  ]).join('\n');
  const structuredRemote = vacancy?.remoteWork === true;
  const jsonLdRemote = /\bTELECOMMUTE\b/i.test(toText(jobPosting?.jobLocationType) ?? '');
  const workFormat = detectWorkFormat({
    structuredRemote,
    jsonLdRemote,
    fullText: fullDescriptionText,
    rssText: rssDescription,
    source,
  });

  const actualSalary = normalizeSalary(vacancy?.salary, jobPosting?.baseSalary);
  const predictedSalary = normalizeSalary(vacancy?.predictedSalary);
  const employmentCode = toText(vacancy?.employment);
  const employment = toText(firstPresent(
    vacancy?.employmentType,
    vacancy?.employment,
    jobPosting?.employmentType,
  ));
  const publishedAt = normalizeDate(firstPresent(
    vacancy?.publishedDate,
    jobPosting?.datePosted,
    source.isoDate,
    source.pubDate,
  ));
  const validThrough = normalizeDate(firstPresent(
    jobPosting?.validThrough,
    vacancy?.expiresAt,
  ));

  const structuredFound = Boolean(vacancy || jobPosting);
  if (!structuredFound) errors.push('structured_vacancy_not_found');
  if (!sourceId) errors.push('source_id_missing');
  if (!url) errors.push('url_missing');
  if (!title) errors.push('title_missing');
  if (!description) errors.push('description_missing');

  const normalizationSource = vacancy
    ? 'habr_ssr'
    : jobPosting
      ? 'json_ld'
      : 'rss_fallback';
  const normalizationQuality = vacancy
    ? 'full'
    : jobPosting
      ? 'fallback'
      : 'failed';

  if (!vacancy && jobPosting) warnings.push('json_ld_fallback_used');
  if (!structuredFound) warnings.push('rss_fallback_used');

  const prefilterDiagnostics = collectPrefilterDiagnostics(source);
  const archived = vacancy?.archived === true;
  const hidden = vacancy?.hidden === true;

  const normalized = {
    schema_version: SCHEMA_VERSION,
    normalizer_version: NORMALIZER_VERSION,
    normalization_source: normalizationSource,
    normalization_quality: normalizationQuality,
    normalization_ok: structuredFound && errors.length === 0,
    normalization_errors: uniqueStrings(errors),
    normalization_warnings: uniqueStrings(warnings),

    source: 'habr_career',
    source_id: sourceId,
    vacancy_key: sourceId ? `habr:${sourceId}` : null,
    source_guid: toText(source.guid),
    url,

    title,
    company,
    company_id: toText(firstPresent(companyData.id, companyData.identifier)),
    company_url: absoluteUrl(firstPresent(companyData.href, companyData.url)),
    company_accredited: companyData.accredited === true,

    published_at: publishedAt,
    valid_through: validThrough,
    archived,
    hidden,
    status: archived ? 'archived' : hidden ? 'hidden' : 'active',

    location: geography.location,
    locations: geography.locations,
    short_geo: geography.short_geo,
    country: geography.country,
    city: geography.city,
    is_tbilisi: geography.is_tbilisi,
    is_georgia: geography.is_georgia,

    ...workFormat,
    geo_policy_hint: geoPolicyHint(workFormat, geography),

    employment,
    employment_code: employmentCode,
    qualification: qualification || null,

    salary_specified: actualSalary.specified,
    salary_from: actualSalary.from,
    salary_to: actualSalary.to,
    salary_currency: actualSalary.currency,
    salary_formatted: actualSalary.formatted,
    salary_period: actualSalary.period,

    predicted_salary_available: predictedSalary.specified,
    predicted_salary_from: predictedSalary.from,
    predicted_salary_to: predictedSalary.to,
    predicted_salary_currency: predictedSalary.currency,
    predicted_salary_formatted: predictedSalary.formatted,
    predicted_salary_period: predictedSalary.period,

    specializations,
    skills,
    description,
    description_length: description.length,
    banner_description: bannerDescription || null,

    ...prefilterDiagnostics,
    prefilter_diagnostics: prefilterDiagnostics,
    salary_filter_applied: false,
  };

  return {
    ...inputItem,
    json: normalized,
  };
} catch (error) {
  const sourceId = extractVacancyId(source.guid, source.link);
  const message = error instanceof Error ? error.message : String(error);

  return {
    ...inputItem,
    json: {
      schema_version: SCHEMA_VERSION,
      normalizer_version: NORMALIZER_VERSION,
      normalization_source: 'failed',
      normalization_quality: 'failed',
      normalization_ok: false,
      normalization_errors: uniqueStrings([
        ...errors,
        `unexpected_normalizer_error: ${message}`,
      ]),
      normalization_warnings: uniqueStrings(warnings),

      source: 'habr_career',
      source_id: sourceId,
      vacancy_key: sourceId ? `habr:${sourceId}` : null,
      source_guid: toText(source.guid),
      url: absoluteUrl(source.link),
      title: toText(firstPresent(source.rss_parsed_vacancy_title, source.title)),
      company: toText(firstPresent(source.creator, source.author)),

      salary_filter_applied: false,
      prefilter_diagnostics: collectPrefilterDiagnostics(source),
    },
  };
}

/**
 * MARK — Full Vacancy Hard Filter
 * Version: 1.0.0
 *
 * n8n Code node mode: Run Once for Each Item
 *
 * Input: normalized vacancy from "Normalize Habr Vacancy".
 * Output: the same vacancy plus four independent gate results and
 *         PASS / REVIEW / REJECT decision.
 *
 * Fixed policy:
 *   - full remote: allowed from any country/city;
 *   - hybrid/office: allowed only in Tbilisi, Georgia;
 *   - salary is never read and never affects the decision;
 *   - seniority is not filtered here (JH-6 owns it);
 *   - REVIEW is kept for audit but does not continue automatically.
 */

const HARD_FILTER_VERSION = '1.0.0';

function isPresent(value) {
  return value !== null &&
    value !== undefined &&
    !(typeof value === 'string' && value.trim() === '');
}

function text(value) {
  return isPresent(value) ? String(value).trim() : '';
}

function normalizedText(value) {
  return text(value)
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/[–—−]/g, '-')
    .replace(/\s+/g, ' ')
    .trim();
}

function stringArray(value) {
  if (!isPresent(value)) return [];

  const values = Array.isArray(value) ? value : [value];
  const result = [];
  const seen = new Set();

  for (const item of values.flat(Infinity)) {
    const itemText = text(item);
    if (!itemText) continue;

    const key = itemText.toLocaleLowerCase('ru-RU');
    if (seen.has(key)) continue;

    seen.add(key);
    result.push(itemText);
  }

  return result;
}

function unique(values) {
  return stringArray(values);
}

function matchesAny(patterns, value) {
  return patterns.some((pattern) => pattern.test(value));
}

function gate(decision, code, reasons = [], warnings = []) {
  return {
    decision,
    code,
    reasons: unique(reasons),
    warnings: unique(warnings),
  };
}

function integrityGate(vacancy) {
  const missing = [];

  if (!isPresent(vacancy.source_id)) missing.push('source_id');
  if (!isPresent(vacancy.url)) missing.push('url');
  if (!isPresent(vacancy.title)) missing.push('title');
  if (!isPresent(vacancy.description)) missing.push('description');

  if (vacancy.normalization_ok !== true || missing.length > 0) {
    return gate(
      'REVIEW',
      'review_normalization_failed',
      ['Vacancy normalization is incomplete'],
      [
        ...stringArray(vacancy.normalization_errors),
        missing.length ? `Missing fields: ${missing.join(', ')}` : null,
      ],
    );
  }

  return gate(
    'PASS',
    'normalization_valid',
    ['Normalized vacancy contract is valid'],
  );
}

function statusGate(vacancy) {
  const status = normalizedText(vacancy.status);

  if (vacancy.archived === true || status === 'archived') {
    return gate(
      'REJECT',
      'reject_vacancy_archived',
      ['Vacancy is archived'],
    );
  }

  if (vacancy.hidden === true || status === 'hidden') {
    return gate(
      'REJECT',
      'reject_vacancy_hidden',
      ['Vacancy is hidden'],
    );
  }

  return gate(
    'PASS',
    'vacancy_active',
    ['Vacancy is active'],
  );
}

function geographyFacts(vacancy) {
  const city = normalizedText(vacancy.city);
  const country = normalizedText(vacancy.country);
  const location = normalizedText([
    vacancy.location,
    ...(Array.isArray(vacancy.locations) ? vacancy.locations : []),
    vacancy.short_geo,
  ].filter(Boolean).join(' '));

  const isTbilisi = vacancy.is_tbilisi === true ||
    /(?:^|[^\p{L}])(?:тбилиси|tbilisi|თბილისი)(?=$|[^\p{L}])/iu.test(
      `${city} ${location}`,
    );

  const explicitGeorgia = vacancy.is_georgia === true ||
    /(?:^|[^\p{L}])(?:грузи(?:я|и)|საქართველო)(?=$|[^\p{L}])/iu.test(
      `${country} ${location}`,
    );

  const englishGeorgia = /(?:^|[^\p{L}])georgia(?=$|[^\p{L}])/iu.test(
    `${country} ${location}`,
  );

  const usGeorgia = /\b(?:usa|u\.s\.a|united states|atlanta|georgia,\s*ga|ga,\s*usa)\b/i.test(
    `${country} ${location}`,
  );

  const isGeorgia = isTbilisi || explicitGeorgia || (englishGeorgia && !usGeorgia);
  const locationKnown = Boolean(city || country || location);

  return {
    city: city || null,
    country: country || null,
    is_tbilisi: isTbilisi,
    is_georgia: isGeorgia,
    location_known: locationKnown,
  };
}

function geoWorkGate(vacancy) {
  const workFormat = normalizedText(vacancy.work_format);
  const confidence = normalizedText(vacancy.work_format_confidence);
  const confidenceAllowed = confidence === 'high' || confidence === 'medium';
  const geography = geographyFacts(vacancy);

  if (vacancy.work_format_conflict === true) {
    return {
      ...gate(
        'REVIEW',
        'review_work_format_conflict',
        ['Work-format evidence is contradictory'],
      ),
      geography,
    };
  }

  if (workFormat === 'remote') {
    if (vacancy.remote_denied === true) {
      return {
        ...gate(
          'REJECT',
          'reject_remote_denied',
          ['The vacancy explicitly denies remote work'],
        ),
        geography,
      };
    }

    if (!confidenceAllowed) {
      return {
        ...gate(
          'REVIEW',
          'review_remote_low_confidence',
          ['Remote format has insufficient confidence'],
        ),
        geography,
      };
    }

    return {
      ...gate(
        'PASS',
        'allow_full_remote',
        ['Confirmed full remote work is allowed from any location'],
      ),
      geography,
    };
  }

  if (workFormat === 'hybrid' || workFormat === 'office') {
    const label = workFormat === 'hybrid' ? 'Hybrid' : 'Office';

    if (geography.is_tbilisi && geography.is_georgia) {
      if (!confidenceAllowed) {
        return {
          ...gate(
            'REVIEW',
            `review_${workFormat}_tbilisi_low_confidence`,
            [`${label} in Tbilisi is possible, but format confidence is low`],
          ),
          geography,
        };
      }

      return {
        ...gate(
          'PASS',
          `allow_${workFormat}_tbilisi`,
          [`${label} work is allowed in Tbilisi, Georgia`],
        ),
        geography,
      };
    }

    if (geography.is_tbilisi && !geography.is_georgia) {
      return {
        ...gate(
          'REVIEW',
          'review_tbilisi_country_unconfirmed',
          ['Tbilisi is detected, but Georgia is not confirmed'],
        ),
        geography,
      };
    }

    if (!geography.location_known || (geography.is_georgia && !geography.city)) {
      return {
        ...gate(
          'REVIEW',
          'review_tbilisi_not_confirmed',
          [`${label} work requires a confirmed Tbilisi location`],
        ),
        geography,
      };
    }

    return {
      ...gate(
        'REJECT',
        `reject_${workFormat}_outside_tbilisi`,
        [`${label} work outside Tbilisi is not allowed by the search policy`],
      ),
      geography,
    };
  }

  if (!workFormat || workFormat === 'unknown') {
    return {
      ...gate(
        'REVIEW',
        'review_work_format_unknown',
        ['Work format is not confirmed'],
      ),
      geography,
    };
  }

  return {
    ...gate(
      'REVIEW',
      'review_work_format_unsupported',
      [`Unsupported work format: ${workFormat}`],
    ),
    geography,
  };
}

function fullPageRoleEvidence(vacancy) {
  const title = normalizedText(vacancy.title);
  const description = normalizedText(vacancy.description);
  const skills = normalizedText(stringArray(vacancy.skills).join(' '));
  const searchable = `${title} ${description} ${skills}`;

  const targetTitlePatterns = [
    /\b(?:ai|llm|gen[\s-]*ai|rag|nlp|ml)[\s-]*(?:engineer|developer|разработчик|инженер)\b/i,
    /\b(?:machine learning|artificial intelligence)[\s-]*(?:engineer|developer)\b/i,
    /(?:инженер|разработчик)[^\n]{0,60}(?:\bai\b|\bllm\b|\bии\b|искусственн\p{L}*\s+интеллект)/iu,
    /(?:\bai\b|\bllm\b|\bии\b|генеративн\p{L}*)[^\n]{0,60}(?:инженер|разработчик)/iu,
    /\bprompt[\s-]*(?:engineer|developer)\b/i,
    /промпт[\s-]*инженер/iu,
    /\bdata scientist\b/i,
    /\bmlops\b|\bllmops\b/i,
  ];

  const absoluteOffTargetPatterns = [
    /\b(?:recruiter|talent acquisition|sales manager|marketing manager|customer success)\b/i,
    /(?:рекрутер|менеджер\s+по\s+продаж|маркетолог|hr[\s-]*менеджер|кадров)/iu,
    /\b(?:product|project|account)[\s-]*manager\b/i,
    /(?:продуктов\p{L}*|проектн\p{L}*)\s+менеджер/iu,
    /(?:бизнес|системн|data|данн\p{L}*)[\s-]*аналитик/iu,
    /\b(?:ux|ui)[\s/+-]*designer\b/i,
    /(?:дизайнер|техническ\p{L}*\s+поддержк)/iu,
  ];

  const technicalOffTargetPatterns = [
    /\bfrontend\b|\bfront[\s-]*end\b/i,
    /\b(?:ios|android|mobile)[\s-]*(?:developer|engineer)\b/i,
    /\b(?:qa|test)[\s-]*(?:engineer|automation)\b/i,
    /\b(?:php|1c|битрикс)[\s-]*(?:developer|разработчик)?\b/iu,
    /\bdevops\b/i,
  ];

  const coreAiPatterns = [
    { name: 'develop_ai_systems', regex: /(?:разрабаты|созда|проектир|стро|внедря|develop|build|design|implement)[^.!?\n]{0,100}(?:\bai\b|\bии\b|\bllm\b|rag|генеративн\p{L}*\s+(?:ии|модел)|искусственн\p{L}*\s+интеллект)/iu },
    { name: 'develop_ai_agents', regex: /(?:разрабаты|созда|проектир|стро|develop|build|design)[^.!?\n]{0,100}(?:ai[\s-]*agent|ии[\s-]*агент|агентн\p{L}*\s+систем)/iu },
    { name: 'build_rag', regex: /(?:разрабаты|созда|проектир|стро|develop|build|design|implement)[^.!?\n]{0,100}\brag\b/iu },
    { name: 'integrate_llm', regex: /(?:интегрир|подключ|integrat|orchestrat)[^.!?\n]{0,100}(?:\bllm\b|\bai\b|модел|agent)/iu },
    { name: 'train_models', regex: /(?:обуч|дообуч|fine[\s-]*tun|train)[^.!?\n]{0,100}(?:модел|\bllm\b|нейросет|model)/iu },
    { name: 'model_inference', regex: /(?:inference|инференс|model serving|обслуживан\p{L}*\s+модел)/iu },
    { name: 'evaluate_llm', regex: /(?:оценк|тестир|evaluat)[^.!?\n]{0,100}(?:\bllm\b|ai[\s-]*систем|модел)/iu },
  ];

  const implementationPatterns = [
    { name: 'LangChain', regex: /\blangchain\b/i },
    { name: 'LangGraph', regex: /\blanggraph\b/i },
    { name: 'LlamaIndex', regex: /\bllamaindex\b/i },
    { name: 'CrewAI', regex: /\bcrewai\b/i },
    { name: 'AutoGen', regex: /\bautogen\b/i },
    { name: 'RAG', regex: /\brag\b/i },
    { name: 'LLM', regex: /\bllm\b/i },
    { name: 'MCP', regex: /\bmcp\b/i },
    { name: 'Embeddings', regex: /\bembeddings?\b/i },
    { name: 'Vector Search', regex: /\bvector (?:database|search|db)\b/i },
    {
      name: 'Vector Database',
      regex: /\b(?:qdrant|faiss|chroma|pinecone|weaviate|milvus|pgvector)\b/i,
    },
    {
      name: 'AI Provider API',
      regex: /\b(?:openai|anthropic|nvidia|gemini)[\s-]*(?:api|nim)?\b/i,
    },
  ];

  const coreSignals = coreAiPatterns
    .filter((pattern) => pattern.regex.test(description))
    .map((pattern) => pattern.name);

  const implementationSignals = implementationPatterns
    .filter((pattern) => pattern.regex.test(searchable))
    .map((pattern) => pattern.name);

  return {
    target_title: matchesAny(targetTitlePatterns, title),
    absolute_off_target_title: matchesAny(absoluteOffTargetPatterns, title),
    technical_off_target_title: matchesAny(technicalOffTargetPatterns, title),
    core_ai_signals: unique(coreSignals),
    implementation_signals: unique(implementationSignals),
  };
}

function roleGate(vacancy) {
  const prefilterDecision = text(vacancy.prefilter_decision).toUpperCase();
  const roleClass = normalizedText(vacancy.title_role_class);
  const targetTier = text(vacancy.target_role_tier).toUpperCase();

  const targetRoles = stringArray(vacancy.matched_target_roles);
  const adjacentRoles = stringArray(vacancy.matched_adjacent_roles);
  const absoluteOffTarget = stringArray(vacancy.matched_absolute_off_target_roles);
  const softOffTarget = stringArray(vacancy.matched_soft_off_target_roles);
  const stackOffTarget = stringArray(vacancy.matched_stack_off_target_roles);
  const prefilterCore = stringArray(vacancy.matched_core_ai_work_signals);
  const substantiveAi = stringArray(vacancy.matched_substantive_ai_categories);
  const prefilterImplementation = stringArray(vacancy.matched_ai_implementation_signals);
  const fullPage = fullPageRoleEvidence(vacancy);

  const coreSignals = unique([prefilterCore, fullPage.core_ai_signals]);
  const implementationSignals = unique([
    prefilterImplementation,
    fullPage.implementation_signals,
  ]);

  const hasTargetEvidence =
    targetRoles.length > 0 ||
    roleClass === 'target' ||
    fullPage.target_title;

  const hasAdjacentEvidence =
    adjacentRoles.length > 0 ||
    roleClass === 'adjacent';

  const hasCoreAiWork = coreSignals.length > 0;
  const hasSubstantiveAi = substantiveAi.length > 0 || implementationSignals.length >= 2;
  const hasAbsoluteOffTarget = absoluteOffTarget.length > 0 || fullPage.absolute_off_target_title;
  const hasTechnicalOffTarget =
    softOffTarget.length > 0 ||
    stackOffTarget.length > 0 ||
    fullPage.technical_off_target_title;

  const evidence = {
    role_class: roleClass || 'unknown',
    target_tier: targetTier || null,
    target_roles: targetRoles,
    adjacent_roles: adjacentRoles,
    absolute_off_target_roles: absoluteOffTarget,
    soft_off_target_roles: softOffTarget,
    stack_off_target_roles: stackOffTarget,
    core_ai_signals: coreSignals,
    substantive_ai_categories: substantiveAi,
    implementation_signals: implementationSignals,
  };

  if (prefilterDecision === 'REJECT') {
    return {
      ...gate(
        'REJECT',
        'reject_prefilter_rejected_role',
        ['The vacancy was classified as irrelevant by the RSS pre-filter'],
      ),
      evidence,
    };
  }

  if (hasAbsoluteOffTarget) {
    return {
      ...gate(
        'REJECT',
        'reject_absolute_off_target_role',
        ['Vacancy title belongs to a non-target profession'],
      ),
      evidence,
    };
  }

  if (hasTechnicalOffTarget && !hasTargetEvidence && !hasCoreAiWork) {
    return {
      ...gate(
        'REJECT',
        'reject_technical_off_target_without_ai_work',
        ['Technical role has no confirmed core AI engineering work'],
      ),
      evidence,
    };
  }

  if (hasTechnicalOffTarget && hasCoreAiWork && !hasTargetEvidence) {
    return {
      ...gate(
        'REVIEW',
        'review_technical_off_target_with_ai_work',
        ['Non-target technical title contains substantive AI engineering work'],
      ),
      evidence,
    };
  }

  if (hasTargetEvidence && (hasSubstantiveAi || hasCoreAiWork)) {
    return {
      ...gate(
        'PASS',
        'allow_target_ai_role',
        ['Target AI role with substantive AI evidence'],
      ),
      evidence,
    };
  }

  if (hasAdjacentEvidence && (hasCoreAiWork || hasSubstantiveAi)) {
    return {
      ...gate(
        'PASS',
        'allow_adjacent_role_with_ai_work',
        ['Adjacent role contains substantive AI engineering work'],
      ),
      evidence,
    };
  }

  if (prefilterDecision === 'PASS' && (hasCoreAiWork || hasSubstantiveAi)) {
    return {
      ...gate(
        'PASS',
        'allow_prefilter_confirmed_ai_role',
        ['Pre-filter PASS is supported by full-vacancy AI evidence'],
      ),
      evidence,
    };
  }

  if (prefilterDecision === 'REVIEW' || hasCoreAiWork || hasSubstantiveAi) {
    return {
      ...gate(
        'REVIEW',
        'review_ambiguous_ai_role',
        ['AI relevance exists, but the profession remains ambiguous'],
      ),
      evidence,
    };
  }

  return {
    ...gate(
      'REJECT',
      'reject_no_substantive_ai_role_evidence',
      ['No substantive AI engineering role evidence was confirmed'],
    ),
    evidence,
  };
}

function aggregateGates(gates) {
  const values = Object.values(gates);
  const rejected = values.find((item) => item.decision === 'REJECT');
  const review = values.find((item) => item.decision === 'REVIEW');
  const primary = rejected ?? review;

  return {
    decision: rejected ? 'REJECT' : review ? 'REVIEW' : 'PASS',
    code: primary?.code ?? 'allow_all_hard_filter_gates',
    reasons: unique(values.flatMap((item) => item.reasons)),
    warnings: unique(values.flatMap((item) => item.warnings)),
  };
}

const inputItem = $input.item;
const vacancy = inputItem?.json ?? {};

const gates = {
  integrity: integrityGate(vacancy),
  status: statusGate(vacancy),
  geo_work: geoWorkGate(vacancy),
  role: roleGate(vacancy),
};

const result = aggregateGates(gates);
const hardFilterPassed = result.decision === 'PASS';

return {
  ...inputItem,
  json: {
    ...vacancy,

    hard_filter_version: HARD_FILTER_VERSION,
    hard_filter_decision: result.decision,
    hard_filter_code: result.code,
    hard_filter_passed: hardFilterPassed,
    should_continue_to_level_filter: hardFilterPassed,
    hard_filter_reasons: result.reasons,
    hard_filter_warnings: result.warnings,

    hard_filter_integrity_gate: gates.integrity,
    hard_filter_status_gate: gates.status,
    hard_filter_geo_work_gate: gates.geo_work,
    hard_filter_role_gate: gates.role,

    salary_filter_applied: false,
  },
};

/**
 * MARK — Vacancy Level Filter
 * Version: 1.0.0
 *
 * n8n Code node mode: Run Once for Each Item
 *
 * Policy:
 *   - Junior / Intern: PASS;
 *   - Middle: PASS unless experience requirements make it a stretch;
 *   - reasonable 2–4 year or unknown-level roles: STRETCH and continue;
 *   - explicit Senior / Lead / Principal / Staff / Head / Architect: REJECT;
 *   - explicit minimum 5+ years: REJECT;
 *   - salary and work geography are not evaluated here.
 */

const LEVEL_FILTER_VERSION = '1.0.0';

function isPresent(value) {
  return value !== null &&
    value !== undefined &&
    !(typeof value === 'string' && value.trim() === '');
}

function text(value) {
  return isPresent(value) ? String(value).trim() : '';
}

function normalizeText(value) {
  return text(value)
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/[–—−]/g, '-')
    .replace(/\s+/g, ' ')
    .trim();
}

function stringArray(value) {
  if (!isPresent(value)) return [];

  const values = Array.isArray(value) ? value : [value];
  const result = [];
  const seen = new Set();

  for (const item of values.flat(Infinity)) {
    const itemText = text(item);
    if (!itemText) continue;

    const key = itemText.toLocaleLowerCase('ru-RU');
    if (seen.has(key)) continue;

    seen.add(key);
    result.push(itemText);
  }

  return result;
}

function decision(value, code, reasons = [], warnings = []) {
  return {
    decision: value,
    code,
    reasons: stringArray(reasons),
    warnings: stringArray(warnings),
  };
}

function replaceNumberWords(value) {
  const replacements = [
    [/(?:^|[^\p{L}])(?:одного|один|одна|one)(?=$|[^\p{L}])/giu, ' 1 '],
    [/(?:^|[^\p{L}])(?:двух|два|две|two)(?=$|[^\p{L}])/giu, ' 2 '],
    [/(?:^|[^\p{L}])(?:трех|три|three)(?=$|[^\p{L}])/giu, ' 3 '],
    [/(?:^|[^\p{L}])(?:четырех|четыре|four)(?=$|[^\p{L}])/giu, ' 4 '],
    [/(?:^|[^\p{L}])(?:пяти|пять|five)(?=$|[^\p{L}])/giu, ' 5 '],
    [/(?:^|[^\p{L}])(?:шести|шесть|six)(?=$|[^\p{L}])/giu, ' 6 '],
    [/(?:^|[^\p{L}])(?:семи|семь|seven)(?=$|[^\p{L}])/giu, ' 7 '],
    [/(?:^|[^\p{L}])(?:восьми|восемь|eight)(?=$|[^\p{L}])/giu, ' 8 '],
    [/(?:^|[^\p{L}])(?:девяти|девять|nine)(?=$|[^\p{L}])/giu, ' 9 '],
    [/(?:^|[^\p{L}])(?:десяти|десять|ten)(?=$|[^\p{L}])/giu, ' 10 '],
  ];

  let result = normalizeText(value);
  for (const [pattern, replacement] of replacements) {
    result = result.replace(pattern, replacement);
  }

  return result.replace(/\s+/g, ' ').trim();
}

function extractExperience(description) {
  const value = replaceNumberWords(description);
  const matches = [];

  const patterns = [
    /(?:опыт\p{L}*|experience)[^.!?\n]{0,70}?(?:не\s+менее|минимум|от|at\s+least|minimum(?:\s+of)?)?\s*(\d{1,2})\s*(?:\+|(?:-|до|to)\s*(\d{1,2}))?\s*(?:лет|год\p{L}*|years?)/giu,
    /(\d{1,2})\s*(?:\+|(?:-|до|to)\s*(\d{1,2}))?\s*(?:лет|год\p{L}*|years?)[^.!?\n]{0,50}?(?:опыт\p{L}*|experience)/giu,
    /(?:не\s+менее|минимум|от|at\s+least|minimum(?:\s+of)?)\s*(\d{1,2})\s*(?:\+|(?:-|до|to)\s*(\d{1,2}))?\s*(?:лет|год\p{L}*|years?)/giu,
  ];

  for (const pattern of patterns) {
    let match;

    while ((match = pattern.exec(value)) !== null) {
      const min = Number(match[1]);
      const max = match[2] ? Number(match[2]) : null;

      if (!Number.isFinite(min) || min < 0 || min > 30) continue;
      if (max !== null && (!Number.isFinite(max) || max < min || max > 40)) continue;

      matches.push({
        min,
        max,
        evidence: match[0].trim(),
      });
    }
  }

  const deduplicated = [];
  const seen = new Set();

  for (const item of matches) {
    const key = `${item.min}:${item.max ?? ''}:${item.evidence}`;
    if (seen.has(key)) continue;
    seen.add(key);
    deduplicated.push(item);
  }

  return deduplicated;
}

function parseHintNumber(value) {
  if (!isPresent(value)) return null;

  const number = Number(value);
  return Number.isFinite(number) && number >= 0 && number <= 40
    ? number
    : null;
}

function experienceEvidence(vacancy) {
  const fullPage = extractExperience(vacancy.description);
  const prefilterMin = parseHintNumber(vacancy.experience_min_years_hint);
  const prefilterMax = parseHintNumber(vacancy.experience_max_years_hint);

  if (fullPage.length > 0) {
    return {
      min_years: Math.max(...fullPage.map((item) => item.min)),
      max_years: Math.max(
        ...fullPage.map((item) => item.max ?? item.min),
      ),
      confidence: 'high',
      source: 'full_description',
      signals: stringArray(fullPage.map((item) => item.evidence)),
    };
  }

  if (prefilterMin !== null || prefilterMax !== null) {
    return {
      min_years: prefilterMin,
      max_years: prefilterMax ?? prefilterMin,
      confidence: 'medium',
      source: 'rss_prefilter',
      signals: stringArray(vacancy.matched_experience_signals),
    };
  }

  return {
    min_years: null,
    max_years: null,
    confidence: 'low',
    source: 'not_found',
    signals: [],
  };
}

function titleLevelEvidence(title) {
  const value = normalizeText(title);

  const highLevelPatterns = [
    { level: 'lead', regex: /(?:^|[^\p{L}])(?:team[\s-]*lead|tech[\s-]*lead|lead|лид|ведущ\p{L}*)(?=$|[^\p{L}])/iu },
    { level: 'principal', regex: /(?:^|[^\p{L}])principal(?=$|[^\p{L}])/iu },
    { level: 'staff', regex: /(?:^|[^\p{L}])staff(?=$|[^\p{L}])/iu },
    { level: 'head', regex: /(?:^|[^\p{L}])(?:head|руководител\p{L}*)(?=$|[^\p{L}])/iu },
    { level: 'architect', regex: /(?:^|[^\p{L}])(?:architect|архитектор\p{L}*)(?=$|[^\p{L}])/iu },
    { level: 'senior', regex: /(?:^|[^\p{L}])(?:senior|sr\.?|сеньор|старш\p{L}*)(?=$|[^\p{L}])/iu },
  ];

  for (const item of highLevelPatterns) {
    if (item.regex.test(value)) {
      return {
        level: item.level,
        confidence: 'high',
        source: 'title',
        signal: item.regex.source,
        high_level: true,
      };
    }
  }

  if (/(?:^|[^\p{L}])(?:junior|jr\.?|джун\p{L}*|начинающ\p{L}*)(?=$|[^\p{L}])/iu.test(value)) {
    return {
      level: 'junior',
      confidence: 'high',
      source: 'title',
      signal: 'junior_title',
      high_level: false,
    };
  }

  if (/(?:^|[^\p{L}])(?:intern|trainee|стажер\p{L}*)(?=$|[^\p{L}])/iu.test(value)) {
    return {
      level: 'intern',
      confidence: 'high',
      source: 'title',
      signal: 'intern_title',
      high_level: false,
    };
  }

  if (/(?:^|[^\p{L}])(?:middle\+|middle[\s-]*plus|мидл\+)(?=$|[^\p{L}])/iu.test(value)) {
    return {
      level: 'middle_plus',
      confidence: 'high',
      source: 'title',
      signal: 'middle_plus_title',
      high_level: false,
    };
  }

  if (/(?:^|[^\p{L}])(?:middle|mid[\s-]*level|мидл\p{L}*)(?=$|[^\p{L}])/iu.test(value)) {
    return {
      level: 'middle',
      confidence: 'high',
      source: 'title',
      signal: 'middle_title',
      high_level: false,
    };
  }

  return {
    level: 'unknown',
    confidence: 'low',
    source: 'not_found',
    signal: null,
    high_level: false,
  };
}

function explicitHighLevelRequirement(description) {
  const value = normalizeText(description);
  const patterns = [
    { level: 'senior', regex: /(?:ищем|позици\p{L}*|уров(?:ень|ня)|level)[^.!?\n]{0,50}(?:senior|сеньор|старш\p{L}*)/iu },
    { level: 'lead', regex: /(?:ищем|позици\p{L}*|уров(?:ень|ня)|level)[^.!?\n]{0,50}(?:lead|лид|ведущ\p{L}*)/iu },
    { level: 'principal', regex: /(?:ищем|позици\p{L}*|level)[^.!?\n]{0,50}principal/iu },
    { level: 'staff', regex: /(?:ищем|позици\p{L}*|level)[^.!?\n]{0,50}staff/iu },
  ];

  return patterns.find((item) => item.regex.test(value)) ?? null;
}

function classifyLevel(vacancy) {
  if (
    vacancy.hard_filter_decision &&
    vacancy.hard_filter_decision !== 'PASS'
  ) {
    return decision(
      'REVIEW',
      'review_hard_filter_not_passed',
      ['Item reached Level Filter without a Hard Filter PASS'],
    );
  }

  const titleEvidence = titleLevelEvidence(vacancy.title);
  const experience = experienceEvidence(vacancy);
  const highRequirement = explicitHighLevelRequirement(vacancy.description);
  const prefilterLevels = stringArray(vacancy.matched_level_categories)
    .map((item) => item.toUpperCase());
  const prefilterRisk = normalizeText(vacancy.seniority_risk_hint);

  if (titleEvidence.high_level) {
    return {
      ...decision(
        'REJECT',
        `reject_explicit_${titleEvidence.level}_title`,
        [`Title explicitly requires ${titleEvidence.level} level`],
      ),
      inferred_level: titleEvidence.level,
      level_confidence: 'high',
      title_evidence: titleEvidence,
      experience,
    };
  }

  if (highRequirement) {
    return {
      ...decision(
        'REJECT',
        `reject_explicit_${highRequirement.level}_requirement`,
        [`Description explicitly requires ${highRequirement.level} level`],
      ),
      inferred_level: highRequirement.level,
      level_confidence: 'high',
      title_evidence: titleEvidence,
      experience,
    };
  }

  if (experience.min_years !== null && experience.min_years >= 5) {
    return {
      ...decision(
        'REJECT',
        'reject_minimum_five_years',
        [`Minimum experience requirement is ${experience.min_years} years`],
      ),
      inferred_level: 'senior',
      level_confidence: experience.confidence,
      title_evidence: titleEvidence,
      experience,
    };
  }

  if (titleEvidence.level === 'junior' || titleEvidence.level === 'intern') {
    return {
      ...decision(
        'PASS',
        `allow_${titleEvidence.level}_role`,
        [`Explicit ${titleEvidence.level} role is within the target range`],
      ),
      inferred_level: titleEvidence.level,
      level_confidence: 'high',
      title_evidence: titleEvidence,
      experience,
    };
  }

  if (titleEvidence.level === 'middle') {
    const isStretch = experience.min_years !== null && experience.min_years >= 3;

    return {
      ...decision(
        isStretch ? 'STRETCH' : 'PASS',
        isStretch ? 'stretch_middle_experience' : 'allow_middle_role',
        [
          isStretch
            ? `Middle role requests ${experience.min_years}+ years`
            : 'Explicit Middle role is within the target range',
        ],
      ),
      inferred_level: 'middle',
      level_confidence: 'high',
      title_evidence: titleEvidence,
      experience,
    };
  }

  if (titleEvidence.level === 'middle_plus') {
    return {
      ...decision(
        'STRETCH',
        'stretch_middle_plus_role',
        ['Middle+ is allowed as a stretch vacancy'],
      ),
      inferred_level: 'middle_plus',
      level_confidence: 'high',
      title_evidence: titleEvidence,
      experience,
    };
  }

  if (experience.min_years !== null && experience.min_years >= 3) {
    return {
      ...decision(
        'STRETCH',
        'stretch_three_to_four_years',
        [`Vacancy requests ${experience.min_years}+ years but is below the hard 5-year cutoff`],
      ),
      inferred_level: experience.min_years >= 4 ? 'middle_plus' : 'middle',
      level_confidence: experience.confidence,
      title_evidence: titleEvidence,
      experience,
    };
  }

  if (experience.min_years === 2) {
    return {
      ...decision(
        'STRETCH',
        'stretch_two_years',
        ['Two years of experience is a reasonable stretch requirement'],
      ),
      inferred_level: 'junior_plus',
      level_confidence: experience.confidence,
      title_evidence: titleEvidence,
      experience,
    };
  }

  if (experience.min_years !== null && experience.min_years <= 1) {
    return {
      ...decision(
        'PASS',
        'allow_entry_experience',
        [`Experience requirement is ${experience.min_years}–1 years`],
      ),
      inferred_level: titleEvidence.level === 'unknown' ? 'junior' : titleEvidence.level,
      level_confidence: experience.confidence,
      title_evidence: titleEvidence,
      experience,
    };
  }

  const prefilterHigh = prefilterLevels.some((item) =>
    ['SENIOR', 'LEAD', 'PRINCIPAL', 'STAFF', 'HEAD', 'ARCHITECT'].includes(item),
  );

  if (prefilterHigh || prefilterRisk === 'high') {
    return {
      ...decision(
        'STRETCH',
        'stretch_unconfirmed_high_level_hint',
        ['High-level RSS hint was not confirmed by the full title or requirements'],
        ['AI scorer should inspect seniority carefully'],
      ),
      inferred_level: 'unknown',
      level_confidence: 'low',
      title_evidence: titleEvidence,
      experience,
    };
  }

  return {
    ...decision(
      'STRETCH',
      'stretch_level_not_specified',
      ['Level is not specified; keep the vacancy for AI evaluation'],
    ),
    inferred_level: 'unknown',
    level_confidence: 'low',
    title_evidence: titleEvidence,
    experience,
  };
}

const inputItem = $input.item;
const vacancy = inputItem?.json ?? {};
const result = classifyLevel(vacancy);
const shouldContinue = result.decision === 'PASS' || result.decision === 'STRETCH';

return {
  ...inputItem,
  json: {
    ...vacancy,

    level_filter_version: LEVEL_FILTER_VERSION,
    level_filter_decision: result.decision,
    level_filter_code: result.code,
    level_filter_passed: shouldContinue,
    should_continue_to_candidate_profile: shouldContinue,

    inferred_level: result.inferred_level ?? 'unknown',
    level_confidence: result.level_confidence ?? 'low',
    required_experience_min_years: result.experience?.min_years ?? null,
    required_experience_max_years: result.experience?.max_years ?? null,
    experience_evidence_source: result.experience?.source ?? 'not_found',
    matched_full_page_experience_signals: result.experience?.signals ?? [],
    level_title_evidence: result.title_evidence ?? null,

    level_filter_reasons: result.reasons,
    level_filter_warnings: result.warnings,
    seniority_filter_applied: true,
  },
};
